def _parse_status_filter(value: str) -> set[str]:
    """Normalize a comma-separated status filter for exact matching."""
    return {status.strip().casefold() for status in value.split(",") if status.strip()}


def _filter_applications_by_status(
    applications: List[Dict[str, Any]],
    sync_status: str,
    health_status: str,
) -> List[Dict[str, Any]]:
    """Filter applications by sync and health status before pagination."""
    requested_sync_statuses = _parse_status_filter(sync_status)
    requested_health_statuses = _parse_status_filter(health_status)

    if not requested_sync_statuses and not requested_health_statuses:
        return applications

    filtered_applications = []
    for application in applications:
        status = application.get("status", {})
        actual_sync_status = status.get("sync", {}).get("status", "").casefold()
        actual_health_status = status.get("health", {}).get("status", "").casefold()

        if requested_sync_statuses and actual_sync_status not in requested_sync_statuses:
            continue
        if requested_health_statuses and actual_health_status not in requested_health_statuses:
            continue
        filtered_applications.append(application)

    return filtered_applications


async def list_applications(
    project: str = "",
    name: str = "",
    repo: str = "",
    namespace: str = "",
    refresh: str = "",
    sync_status: str = "",
    health_status: str = "",
    summary_only: bool = True,
    page: int = 1,
    page_size: int = 20,
) -> Dict[str, Any]:
    """
    List applications in ArgoCD with filtering and pagination options

    Args:
        project: Filter applications by project name
        name: Filter applications by name
        repo: Filter applications by repository URL
        namespace: Filter applications by namespace
        refresh: Forces application reconciliation if set to 'hard' or 'normal'
        sync_status: Filter by exact sync status. Accepts comma-separated values,
            such as ``OutOfSync,Unknown`` (case-insensitive).
        health_status: Filter by exact health status. Accepts comma-separated values,
            such as ``Degraded,Missing`` (case-insensitive). Use this filter instead
            of scanning every page when looking for failed or unhealthy applications.
        summary_only: If True, return only summary information (default: True)
        page: Page number (1-indexed, default: 1)
        page_size: Number of items per page (default: 20, max: 100)

    Returns:
        Paginated list of applications with metadata:
        {
            "items": [...],
            "pagination": {
                "page": 1,
                "page_size": 20,
                "total_items": 819,
                "total_pages": 41,
                "has_next": true,
                "has_prev": false
            }
        }
    """
    params = {}

    if project:
        params["project"] = project

    if name:
        params["name"] = name

    if repo:
        params["repo"] = repo

    if namespace:
        params["appNamespace"] = namespace

    if refresh in ["hard", "normal"]:
        params["refresh"] = refresh

    success, data = await make_api_request("/api/v1/applications", params=params)

    if not success:
        return {"error": data.get("error", "Failed to retrieve applications")}

    # Handle None data
    if data is None:
        return {"error": "No data received from API"}

    # Handle None items
    if data.get("items") is None:
        response = {
            "items": [],
            "pagination": {
                "page": page,
                "page_size": page_size,
                "total_items": 0,
                "total_pages": 0,
                "has_next": False,
                "has_prev": False
            }
        }
        if summary_only:
            response["summary_only"] = True
        return response

    # Enforce pagination limits
    page = max(1, page)  # Ensure page is at least 1
    page_size = min(100, max(1, page_size))  # Enforce max 100 items per page

    all_items = _filter_applications_by_status(
        data.get("items", []),
        sync_status=sync_status,
        health_status=health_status,
    )
    total_items = len(all_items)
    total_pages = (total_items + page_size - 1) // page_size  # Ceiling division

    # Calculate pagination slice
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size

    # Check if page is out of bounds
    if start_idx >= total_items and total_items > 0:
        return {
            "error": f"Page {page} out of bounds. Total pages: {total_pages}",
            "pagination": {
                "page": page,
                "page_size": page_size,
                "total_items": total_items,
                "total_pages": total_pages,
                "has_next": False,
                "has_prev": page > 1
            }
        }

    paginated_items = all_items[start_idx:end_idx]

    # Build pagination metadata
    pagination_meta = {
        "page": page,
        "page_size": page_size,
        "total_items": total_items,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_prev": page > 1,
        "showing_from": start_idx + 1 if paginated_items else 0,
        "showing_to": start_idx + len(paginated_items)
    }

    # If summary_only is True, return only essential information
    if summary_only:
        summary_items = []
        argocd_base_url = _get_argocd_base_url()
        for app in paginated_items:
            app_name = app.get("metadata", {}).get("name", "")
            app_namespace = app.get("metadata", {}).get("namespace", "")
            summary_item = {
                "name": app_name,
                "namespace": app_namespace,
                "project": app.get("spec", {}).get("project", ""),
                "repo": app.get("spec", {}).get("source", {}).get("repoURL", ""),
                "path": app.get("spec", {}).get("source", {}).get("path", ""),
                "target_revision": app.get("spec", {}).get("source", {}).get("targetRevision", ""),
                "sync_status": app.get("status", {}).get("sync", {}).get("status", ""),
                "health_status": app.get("status", {}).get("health", {}).get("status", ""),
                "phase": app.get("status", {}).get("phase", ""),
            }
            # Add ArgoCD link using common helper
            summary_item = _add_argocd_link_to_app(summary_item)
            summary_items.append(summary_item)

        # Ensure base URL is in response
        return {
            "items": summary_items,
            "pagination": pagination_meta,
            "summary_only": True,
            "argocd_base_url": argocd_base_url
        }

    # Add ArgoCD links to full items using common helper
    argocd_base_url = _get_argocd_base_url()
    for app in paginated_items:
        _add_argocd_link_to_app(app)

    # Ensure base URL is in response
    return {
        "items": paginated_items,
        "pagination": pagination_meta,
        "argocd_base_url": argocd_base_url
    }


